llm.raw_content:
{
  "bioavailability_prediction": "high",
  "claims": [
    {
      "card_ids": ["C38"],
      "claim": "Disopyramide, which shares the central phenyl/2-pyridyl motif and a basic amine side chain with the query, has absolute oral bioavailability of 81.76 ± 17.90% in healthy volunteers, strongly supporting F ≥ 20%.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C18"],
      "claim": "Methadone, a lipophilic basic tertiary amine with a similar propylamine linker, has mean oral bioavailability of 0.86 versus IV in humans, supporting high oral F.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C49"],
      "claim": "Doxylamine, which contains the same phenyl/2-pyridyl central carbon as the query, has oral bioavailability of about 50% in normal subjects, above the 20% threshold.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C08"],
      "claim": "Fexofenadine, despite being a P-gp substrate with a zwitterionic carboxylate, has absolute oral bioavailability of about 30% in humans, still above the 20% threshold and supporting high F for this chemotype.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C14"],
      "claim": "Dextromoramide, a diphenyl tertiary amide with a basic morpholine, is reported to have good oral bioavailability, supporting high F for lipophilic basic central-carbon scaffolds.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C05"],
      "claim": "Loperamide has very low absolute oral bioavailability (0.3%) due to P-gp efflux and low solubility, but its transfer to the query is very low because it lacks the pyridyl motif and has an amide/chlorophenyl structure; this is a weak contradictory signal.",
      "evidence_role": "contradictory"
    }
  ],
  "confidence": "moderate",
  "decision_summary": "The query is a lipophilic basic tertiary amine with a phenyl/2-pyridyl central carbinol, closely related to disopyramide and doxylamine, both of which have human oral F well above 20% (about 80-90% and 50%, respectively). Methadone and fexofenadine also support F ≥ 20%. The only strong low-F analogue, loperamide, has very low transfer due to distinct amide/chlorophenyl/P-gp features. Therefore the balance of evidence predicts high oral bioavailability at the F ≥ 20% threshold.",
  "evidence_gaps": [
    "No direct human oral bioavailability data for the exact query molecule.",
    "The query's very high basic pKa (10.35) and full ionization at pH 7.4 are not directly tested; analogues with somewhat lower pKa may overestimate permeability.",
    "P-gp/BCRP efflux status of the query is unknown; loperamide shows that efflux can cause low F in a related scaffold, but transfer is low.",
    "First-pass metabolism of the 2,6-dimethylpiperidine and tertiary alcohol moieties is uncharacterized."
  ],
  "new_evidence_assessment": [],
  "revision_action": "initial"
}

